package com.example

import com.example.ExamQuestionHelper.QSpec

object HealthLiveExamTeamSportsBank2 {
    private const val T = "කණ්ඩායම් ක්‍රීඩා, ජලජ ක්‍රීඩා හා තරගාවලි සංවිධානය"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("වොලිබෝල් ක්‍රීඩාවේ තීරණාත්මක 5 වන වටය (Deciding 5th set) ජයග්‍රහණය කිරීමට ලබාගත යුතු අවම ලකුණු සංඛ්‍යාව කීයද?", "ලකුණු 2ක පරතරයක් සහිතව ලකුණු 15ක්", "ලකුණු 25ක්", "ලකුණු 21ක්", "ලකුණු 10ක්", "වොලිබෝල් තරගයක අවසන් තීරණාත්මක 5 වන වටය ලකුණු 15 දක්වා පවත්වන අතර ලකුණු 2ක පරතරයක් අනිවාර්ය වේ."),
        q("වොලිබෝල් ක්‍රීඩාවේ පන්දු පිරිනැමීමේදී (Serve) ක්‍රීඩකයා පන්දුවට පහර දීමට පෙර සේවා සීමා රේඛාව පෑගුවහොත් ලැබෙන තීන්දුව කුමක්ද?", "පාද වරදක් (Foot Fault) ලෙස විරුද්ධ පිලට ලකුණක් හා සේවය හිමිවීම", "නැවත සේවය පිරිනැමීමට අවස්ථාව දීම", "කිසිදු වරදක් නොවීම", "ක්‍රීඩකයාට අනතුරු ඇඟවීම පමණි", "සේවය එල්ල කරන මොහොතේ හෝ ඊට පෙර සේවා රේඛාව පෑගීම හෝ සීමාව ඉක්මවා යාම නීති විරෝධී පාද වරදකි."),
        q("වොලිබෝල් ක්‍රීඩාවේ පන්දුව පිරිනැමූ පසු එය දැලේ ස්පර්ශ වී විරුද්ධ පිලේ සීමාව තුළ පතිත වුවහොත් තීරණය කුමක්ද?", "නීත්‍යානුකූල පන්දු පිරිනැමීමක් (Play continues) ලෙස සැලකීම", "අවලංගු සේවයක් ලෙස සලකා ලකුණ අහිමි වීම", "නැවත සේවය පිරිනැමීමට නියෝග කිරීම", "විරුද්ධ පිලට දඬුවම් ලකුණක් දීම", "පිරිනැමූ පන්දුව දැලේ ස්පර්ශ වී විරුද්ධ පිලේ පිටිය තුළට වැටේ නම් ක්‍රීඩාව අඛණ්ඩව ඉදිරියට ගලා යයි."),
        q("වොලිබෝල් ක්‍රීඩාවේ පන්දු සකසන්නා (Setter) විසින් ප්‍රහාරකයාට පහර ගැසීම සඳහා පන්දුව වාතයේ ඔසවා තැබීම හඳුන්වන්නේ කුමන නමකින්ද?", "පන්දු සැකසීම හෙවත් පන්දු එසවීම (Setting / Volleying)", "පන්දු පිළිගැනීම", "පන්දු පිරිනැමීම", "ආවරණය කිරීම", "දෙවන පහර ලෙස පන්දු සකසන්නා විසින් ඉතා නිවැරදිව පන්දුව ප්‍රහාරක කලාපයට එසවීම සැකසීමයි."),
        q("වොලිබෝල් ක්‍රීඩාවේ 5-1 ක්‍රමෝපායික සැලැස්ම (5-1 formation) යනු කුමක්ද?", "ප්‍රහාරකයන් 5 දෙනෙකු සහ එක් ප්‍රධාන පන්දු සකසන්නෙකු යොදා ගන්නා උපායමාර්ගය", "ආරක්ෂකයන් 5ක් සහ ප්‍රහාරකයෙක්", "පන්දු සකසන්නන් 5ක් සහ ප්‍රහාරකයෙක්", "ප්‍රහාරකයන් 5ක් සහ ආදේශකයෙක්", "5-1 උපක්‍රමයේදී මුළු තරගය පුරාම එක් ප්‍රධාන සකසන්නෙකු (Setter) පමණක් ක්‍රීඩා කරයි."),
        q("වොලිබෝල් ක්‍රීඩාවේ 6-2 ක්‍රමෝපායික සැලැස්මේදී (6-2 formation) පන්දු සකසන්නා ලෙස ක්‍රියා කරන්නේ කුමන කලාපයේ ක්‍රීඩකයාද?", "පසුපස කලාපයට මාරු වන ක්‍රීඩකයා (පෙරමුණේ ප්‍රහාරකයන් තිදෙනෙකු රඳවා ගනිමින්)", "ඉදිරිපෙළ මැද ක්‍රීඩකයා", "ලිබරෝ ක්‍රීඩකයා පමණි", "පිටියේ පිටත සිටින ක්‍රීඩකයා", "6-2 ක්‍රමයේදී පසුපස කලාපයේ සිටින සකසන්නා ඉදිරියට පැමිණ පන්දු සකසන බැවින් ඉදිරිපෙළ නිතරම ප්‍රහාරකයන් 3 දෙනෙකු ක්‍රියාත්මක වේ."),
        q("වොලිබෝල් ක්‍රීඩාවේ පන්දුව සුළඟේ පාවී යන සේ භ්‍රමණයකින් තොරව පිරිනමන සේවා වර්ගය කුමක්ද?", "පාවෙන සේවය (Floating Serve)", "කැරකෙන සේවය", "යටි අත් සේවය", "පිටුපස සේවය", "පන්දුවේ කේන්ද්‍රයට කෙළින්ම පහර දීමෙන් භ්‍රමණය අවම කර ප්‍රතිවාදියා රැවටෙන පරිදි පාවී යන පාවෙන සේවය බිහිවේ."),
        q("වොලිබෝල් ක්‍රීඩාවේ පිම්මක් පැන ඉහළ අහසේදී ප්‍රබල වේගයකින් ප්‍රතිවාදී පිලට එල්ල කරන සේවය කුමක්ද?", "පිමි සේවය (Jump Serve)", "යටි අත් සේවය", "පාවෙන සේවය", "පැති සේවය", "ප්‍රහාරක පහරක් එල්ල කරන ආකාරයෙන් පිම්මක් පැන උඩ පැන පහර දීම පිමි සේවයයි."),
        q("දැල්පන්දු ක්‍රීඩාවේ (Netball) ගෝල කණුවක සම්මත උස පොළොවේ සිට අඩි හෝ මීටර් කීයක්ද?", "අඩි 10ක් (මීටර් 3.05ක්)", "අඩි 8ක් (මීටර් 2.44ක්)", "අඩි 12ක් (මීටර් 3.66ක්)", "අඩි 9ක් (මීටර් 2.74ක්)", "දැල්පන්දු ගෝල කණුවක උස අඩි 10ක් හෙවත් මීටර් 3.05කි."),
        q("දැල්පන්දු වළල්ලේ (Ring) ඇතුළත සම්මත විෂ්කම්භය මිලිමීටර හෝ අඟල් කීයද?", "මිලිමීටර 380ක් හෙවත් අඟල් 15ක්", "මිලිමීටර 300ක් හෙවත් අඟල් 12ක්", "මිලිමීටර 450ක් හෙවත් අඟල් 18ක්", "මිලිමීටර 500ක් හෙවත් අඟල් 20ක්", "දැල්පන්දු වළල්ලේ ඇතුළත විෂ්කම්භය මිලිමීටර 380කි."),
        q("දැල්පන්දු ක්‍රීඩා පිටියේ මධ්‍ය වෘත්තයේ (Center Circle) විෂ්කම්භය කොපමණද?", "විෂ්කම්භය මීටර් 0.9ක් (අඩි 3ක්)", "විෂ්කම්භය මීටර් 1.5ක්", "විෂ්කම්භය මීටර් 2.0ක්", "විෂ්කම්භය මීටර් 3.0ක්", "දැල්පන්දු පිටියේ මධ්‍යයේ පිහිටි කුඩා වෘත්තයේ විෂ්කම්භය මීටර් 0.9කි."),
        q("දැල්පන්දු ක්‍රීඩාවේ ගෝල ලබාගැනීමේ අර්ධ වෘත්තාකාර කලාපයේ (Goal Circle) අරය මීටර් කීයද?", "මීටර් 4.9ක් (අඩි 16ක්)", "මීටර් 3.5ක්", "මීටර් 6.0ක්", "මීටර් 2.5ක්", "දැල්පන්දු ගෝල අර්ධ වෘත්තයේ අරය මීටර් 4.9ක් වේ."),
        q("දැල්පන්දු ක්‍රීඩාවේ එකම පිලක ක්‍රීඩිකාවන් දෙදෙනෙකු අතර පන්දුව හුවමාරු කිරීමේදී පන්දුව අහසේ තිබියදී තෙවන ක්‍රීඩිකාවකට අත තැබිය හැකි පරිදි ඇති විය යුතු අවම දුර ප්‍රමාණය කුමක්ද?", "කෙටි පාස් නොවන පරිදි ක්‍රීඩිකාවන් අතර තෙවැන්නෙකුට ඉඩ තිබිය යුතුය (Short pass rule)", "ඕනෑම ළඟ දුරක් ප්‍රමාණවත්ය", "අවම මීටර් 5ක් විය යුතුය", "අතින් අතට මාරු කළ හැක", "දැල්පන්දුවේ අතින් අතට පන්දු දීම තහනම් වන අතර තෙවන ක්‍රීඩිකාවකට බාධා කළ හැකි දුරක් තිබිය යුතුය."),
        q("දැල්පන්දු ක්‍රීඩාවේ ප්‍රතිවාදියාගේ පන්දුව උදුරා ගැනීමේදී (Defending) පන්දුව අතැති ක්‍රීඩිකාවගේ රැඳවුම් පාදයේ සිට තැබිය යුතු අවම නීත්‍යානුකූල දුර කොපමණද?", "මීටර් 0.9ක් (අඩි 3ක්)", "මීටර් 0.5ක්", "මීටර් 1.5ක්", "මීටර් 2.0ක්", "දැල්පන්දු ක්‍රීඩාවේ ආරක්ෂක ක්‍රීඩිකාව පන්දුව අතැති ක්‍රීඩිකාවගේ පාදයේ සිට අවම මීටර් 0.9ක දුරක් තබාගත යුතුය."),
        q("දැල්පන්දු ක්‍රීඩාවේ ක්‍රීඩිකාවන් තිදෙනෙකුට පමණක් සීමා වී ඇතුළු විය හැකි පිටියේ කොටස් 3 කුමක්ද?", "තෙවැනි කොටස් (Goal Thirds සහ Center Third)", "ප්‍රහාරක කලාපය පමණි", "ගෝල කවය පමණි", "බාහිර සීමාව", "දැල්පන්දු පිටිය දිගින් සමාන කොටස් 3කට (Thirds) බෙදා ඇති අතර එක් එක් ක්‍රීඩිකාවට යා හැකි කලාප නීතියෙන් සීමා කර ඇත."),
        q("දැල්පන්දු ක්‍රීඩාවේ පිටියෙන් ඉවතට ගිය පන්දුවක් නැවත පිටිය තුළට යොමු කිරීම (Throw-in) සඳහා ලබාදෙන උපරිම කාලය තත්පර කීයද?", "තත්පර 3ක්", "තත්පර 5ක්", "තත්පර 10ක්", "තත්පර 15ක්", "දැල්පන්දුවේදී පන්දුව ලැබුණු ඕනෑම අවස්ථාවක තත්පර 3ක් ඇතුළත එය විසි කළ යුතුය."),
        q("දැල්පන්දු ක්‍රීඩාවේ බාධා කිරීමක් (Obstruction) හෝ පෞද්ගලික ස්පර්ශයක් (Contact) සිදුවූ විට ලබාදෙන දඬුවම කුමක්ද?", "දඬුවම් පාස් පහරක් (Penalty Pass) හෝ දඬුවම් විදීමක්", "නිදහස් පහරක් පමණි", "ක්‍රීඩිකාව තරගයෙන් ඉවත් කිරීම", "ලකුණු අහිමි වීම", "පෞද්ගලික ස්පර්ශ හෝ බාධා කිරීම් සඳහා ප්‍රතිවාදී පිලට දඬුවම් පාස් පහරක් හිමිවේ."),
        q("දැල්පන්දු ක්‍රීඩාවේ නීති විරෝධී බාධා කිරීමක් සිදුකළ ක්‍රීඩිකාවට පැනවෙන කොන්දේසිය කුමක්ද?", "දඬුවම් පහර ක්‍රියාත්මක වන තුරු අක්‍රියව පැත්තකින් සිටිය යුතුය (Stand out of play)", "පිටියෙන් සම්පූර්ණයෙන්ම ඉවත් විය යුතුය", "ගෝල කණුව අසලට යා යුතුය", "කිසිදු සීමාවක් නැත", "වරද කළ ක්‍රීඩිකාව දඬුවම් පහර නිමවන තුරු කිසිදු ක්‍රියාවක නොයෙදී අක්‍රියව පැත්තකින් සිටිය යුතුය."),
        q("දැල්පන්දු ක්‍රීඩාවේ පන්දුව එකවර ක්‍රීඩිකාවන් දෙදෙනෙකු විසින් තදින් අල්ලා ගත් විට විනිසුරු ලබාදෙන තීරණය කුමක්ද?", "පන්දු උඩ දැමීමක් (Toss-up)", "කාසියේ වාසිය බැලීම", "ගෝල් කික් පහරක්", "නිදහස් පාස් පහරක්", "ක්‍රීඩිකාවන් දෙදෙනා අතර මීටර් 0.9ක පරතරයක් තබා විනිසුරු පන්දුව උඩ දමයි."),
        q("දැල්පන්දු ක්‍රීඩා තරගයක සම්පූර්ණ කාලය විනාඩි කීයකින් සහ කාර්තු කීයකින් සමන්විත වේද?", "විනාඩි 15 බැගින් වූ කාර්තු 4ක් (මුළු විනාඩි 60ක්)", "විනාඩි 20 බැගින් අඩ 2ක්", "විනාඩි 10 බැගින් කාර්තු 4ක්", "විනාඩි 45 බැගින් අඩ 2ක්", "ජාත්‍යන්තර දැල්පන්දු තරගයක් විනාඩි 15 කාර්තු 4කින් යුක්ත වේ."),
        q("පාපන්දු ක්‍රීඩා පිටියක මධ්‍ය වෘත්තයේ (Center Circle) අරය (Radius) මීටර් කීයද?", "මීටර් 9.15කි (යාර 10කි)", "මීටර් 7.5කි", "මීටර් 11කි", "මීටර් 5කි", "පාපන්දු පිටියේ මධ්‍ය වෘත්තයේ අරය මීටර් 9.15ක් හෙවත් යාර 10කි."),
        q("පාපන්දු ක්‍රීඩාවේ දඬුවම් පහර ලක්ෂ්‍යයේ (Penalty Spot) සිට ගෝල රේඛාවට ඇති සම්මත දුර මීටර් කීයද?", "මීටර් 11ක් (යාර 12ක්)", "මීටර් 9.15ක්", "මීටර් 15ක්", "මීටර් 16.5ක්", "දඬුවම් පහර ලක්ෂ්‍යය ගෝල රේඛාවේ මැද සිට මීටර් 11ක් (යාර 12ක්) දුරින් පිහිටයි."),
        q("පාපන්දු ක්‍රීඩාවේ දඬුවම් පහර පෙට්ටියේ (Penalty Box) මිනුම් සම්මත ලෙස කොපමණද?", "මීටර් 16.5 × 40.32 (යාර 18 පෙට්ටිය)", "මීටර් 10 × 20", "මීටර් 5.5 × 18.32", "මීටර් 25 × 50", "දඬුවම් පෙට්ටිය ගෝල කණුවල සිට දෙපසට මීටර් 16.5ක් සහ ඉදිරියට මීටර් 16.5ක් විහිදේ."),
        q("පාපන්දු ක්‍රීඩාවේ සෘජු නිදහස් පහරක් (Direct Free Kick) සහ වක්‍ර නිදහස් පහරක් (Indirect Free Kick) අතර ඇති ප්‍රධාන වෙනස කුමක්ද?", "සෘජු පහරකදී කෙළින්ම ගෝලයක් ලබාගත හැකි අතර වක්‍ර පහරකදී තවත් ක්‍රීඩකයෙකු ස්පර්ශ විය යුතුය", "සෘජු පහර ගසන්නේ අතින් වීම", "වක්‍ර පහරකදී පන්දුව නොනවත්වා පයින් ගැසිය යුතු වීම", "කිසිදු වෙනසක් නැත", "සෘජු නිදහස් පහරකදී පන්දුව කෙළින්ම දැල තුළට ගියද ගෝලය වලංගු වේ."),
        q("පාපන්දු ක්‍රීඩාවේ ක්‍රීඩකයෙකු තම පාලනයකින් තොරව අත්වැරදීමකින් තමාගේම ගෝල දැල තුළට පන්දුව යොමු කිරීම හඳුන්වන්නේ කෙසේද?", "ස්වයං ගෝලය හෙවත් ඕන් ගෝල් (Own Goal)", "දඬුවම් ගෝලය", "අවලංගු ගෝලය", "නිදහස් ගෝලය", "තමාගේම කණ්ඩායමේ ගෝල රේඛාව තුළට පන්දුව යැවීම ස්වයං ගෝලයක් ලෙස ප්‍රතිවාදීන්ට එකතු වේ."),
        q("පාපන්දු ක්‍රීඩාවේ ප්‍රතිවාදී පිලේ ක්‍රීඩකයෙකු ගෝල රේඛාවෙන් පිටතට පන්දුව යැවූ විට පන්දුව නැවත ක්‍රීඩාවට එක් කරන්නේ කෙසේද?", "ගෝල් කික් පහරකින් (Goal Kick)", "කෝනර් කික් පහරකින්", "ත්‍රෝ ඉන් පහරකින්", "දඬුවම් පහරකින්", "ප්‍රහාරක පිලේ ක්‍රීඩකයෙකුගේ ස්පර්ශයෙන් පන්දුව ගෝලයෙන් පිටතට ගිය විට ගෝල රකින්නා විසින් ගෝල් කික් එකක් ගසයි."),
        q("පාපන්දු ක්‍රීඩාවේ ආරක්ෂක පිලේ ක්‍රීඩකයෙකුගේ ඇඟේ දැවටී පන්දුව ඔවුන්ගේම ගෝල රේඛාවෙන් පිටතට ගිය විට ලැබෙන වාසිය කුමක්ද?", "කොනක පහරක් හෙවත් කෝනර් කික් (Corner Kick)", "ගෝල් කික් පහරක්", "දඬුවම් පහරක්", "ත්‍රෝ ඉන් දැමීමක්", "ආරක්ෂක ක්‍රීඩකයෙකුගේ වැදී ගෝල රේඛාවෙන් පිටතට ගිය විට ප්‍රහාරක පිලට කොනක පහරක් හිමිවේ."),
        q("පාපන්දු ක්‍රීඩාවේ මූලික උපක්‍රමික පෙළගැස්මක් වන 4-4-2 ආකෘතියෙන් නිරූපණය වන්නේ කුමක්ද?", "පසුපස ආරක්ෂකයන් 4ක්, මැදපෙළ 4ක් සහ ඉදිරිපෙළ ප්‍රහාරකයන් 2ක්", "ප්‍රහාරකයන් 4ක්, මැදපෙළ 4ක් සහ ආරක්ෂකයන් 2ක්", "ගෝල රකින්නන් 4ක්", "ආදේශක ක්‍රීඩකයන් සංඛ්‍යාව", "4-4-2 යනු සම්ප්‍රදායික සමබර ආරක්ෂක සහ මැදපෙළ පෙළගැස්මකි."),
        q("පාපන්දු ක්‍රීඩාවේ ප්‍රහාරාත්මක උපක්‍රමයක් වන 4-3-3 ආකෘතියේ විශේෂත්වය කුමක්ද?", "ඉදිරිපෙළ ප්‍රහාරකයන් තිදෙනෙකු යොදා ගනිමින් ප්‍රහාරක ශක්තිය වැඩි කිරීම", "ආරක්ෂාව පමණක් ශක්තිමත් කිරීම", "ගෝල රකින්නන් තිදෙනෙකු සිටීම", "පිටියේ මැද ක්‍රීඩකයන් නොමැති වීම", "4-3-3 ආකෘතියේදී ප්‍රධාන ප්‍රහාරකයා සමග වින්ගර්වරුන් දෙදෙනෙකු ඉදිරිපෙළ මෙහෙයවයි."),
        q("පාපන්දු ක්‍රීඩාවේ ප්‍රධාන විනිසුරුට සහය වීම සඳහා නූතන තරගවලදී යොදා ගන්නා වීඩියෝ තාක්ෂණය හඳුන්වන්නේ කෙසේද?", "VAR තාක්ෂණය (Video Assistant Referee)", "GPS තාක්ෂණය", "Hawkeye තාක්ෂණය", "Snickometer තාක්ෂණය", "ගෝල, රතු කාඩ්පත් සහ දඬුවම් පහර තීන්දු නිවැරදිව ගැනීමට VAR තාක්ෂණය යොදා ගැනේ."),
        q("ක්‍රිකට් ක්‍රීඩාවේ ටෙස්ට් තරගයකදී එක් දිනකට ක්‍රීඩා කළ යුතු අවම ඕවර සංඛ්‍යාව කොපමණද?", "ඕවර 90ක්", "ඕවර 50ක්", "ඕවර 100ක්", "ඕවර 75ක්", "ටෙස්ට් ක්‍රිකට් තරගයක සාමාන්‍ය දිනක නියමිත ඕවර සංඛ්‍යාව 90කි."),
        q("ක්‍රිකට් ක්‍රීඩාවේ එක්දින (ODI) තරගයක මුල් ඕවර 10 තුළ ක්‍රියාත්මක වන පන්දු රැකීමේ සීමාව කුමක්ද?", "පළමු පවර්ප්ලේ අවස්ථාව (Mandatory Powerplay 1)", "අවසන් පවර්ප්ලේ එක", "නිදහස් ඕවර", "තෙවන පවර්ප්ලේ එක", "මුල් ඕවර 10 තුළ යාර 30 සීමාවෙන් පිටත රැඳවිය හැක්කේ පන්දු රකින්නන් දෙදෙනෙකු පමණි."),
        q("ක්‍රිකට් ක්‍රීඩාවේ පන්දු යවන්නා නිපන්දුවක් (No-ball) යැවූ විට විස්සයි-20 සහ එක්දින තරගවලදී පිතිකරුවාට ලැබෙන විශේෂ වරප්‍රසාදය කුමක්ද?", "නිදහස් පහරක් (Free Hit) හිමිවීම", "ලකුණු 5ක් හිමිවීම", "පිතිකරුවාට විවේකයක් ලැබීම", "තරගය ජයග්‍රහණය කිරීම", "නිපන්දුවෙන් පසු ඊළඟ පන්දුවේදී දුවද්දී දැවී යාමක් හැර වෙනත් ආකාරයකින් දැවී යා නොහැක."),
        q("ක්‍රිකට් ක්‍රීඩාවේ පන්දුව පිත්තේ නොවැදී පිතිකරුවාගේ පා ආවරණයේ හෝ ශරීරයේ වැදී ලබාගන්නා ලකුණු හඳුන්වන්නේ කෙසේද?", "ලෙග් බයි ලකුණු (Leg Bye)", "බයි ලකුණු", "වයිඩ් ලකුණු", "නෝ බෝල් ලකුණු", "පිතිකරුවා පන්දුවෙන් වැළකීමට හෝ පහර දීමට උත්සාහ කර ශරීරයේ වැදී ලබාගන්නා ලකුණු ලෙග් බයි වේ."),
        q("ක්‍රිකට් ක්‍රීඩාවේ පන්දුව පිතිකරුට හෝ ඔහුගේ උපකරණයකට කිසිසේත් ස්පර්ශ නොවී කඩුලු රකින්නා පසුකර යාමේදී ලබාගන්නා ලකුණු හඳුන්වන්නේ කෙසේද?", "බයි ලකුණු (Bye)", "ලෙග් බයි", "නෝ බෝල්", "පැනල්ටි ලකුණු", "පිතිකරුගේ ශරීරයේ හෝ පිත්තේ නොවැදී ලබාගන්නා ලකුණු බයි ලකුණු ලෙස සටහන් වේ."),
        q("ක්‍රිකට් ක්‍රීඩාවේ පන්දු රකින්නන් නොමැති හිස් අවකාශ සොයා පන්දුව යොමු කිරීම හඳුන්වන්නේ කුමන නමකින්ද?", "පරතරය සොයා පහර දීම (Placing the ball / Finding gaps)", "උඩපන්දු ගැසීම", "බ්ලොක් කිරීම", "ස්විං කිරීම", "පන්දු රකින්නන් අතර ඇති හිස් තැන් ඔස්සේ පන්දුව ගමන් කරවීම ලකුණු රැස්කිරීමේ දක්ෂතාවයකි."),
        q("ක්‍රිකට් ක්‍රීඩාවේ පන්දු යවන්නා විසින් පිතිකරුවාගේ පාද අසලටම කෙළින්ම පතිත වන සේ යවන වේගවත් පන්දුව හඳුන්වන්නේ කෙසේද?", "යෝකර් පන්දුව (Yorker)", "බවුන්සර් පන්දුව", "ගුග්ලි පන්දුව", "ෆ්ලිපර් පන්දුව", "පිතිකරුවාගේ පාද මුලටම හෝ පොප්පින් ක්‍රීස් රේඛාව අසලට පතිත වන පන්දුව යෝකර් පන්දුවයි."),
        q("එල්ලේ ක්‍රීඩාවේ ධාවකයා ලකුණු ලබාගැනීම සම්පූර්ණ කිරීම සඳහා පිළිවෙළින් පසුකළ යුතු නැවතුම් කණු (Bases) ගණන කීයද?", "නැවතුම් කණු 3ක් පසුකර නිවසට පැමිණිය යුතුය", "නැවතුම් කණු 2ක්", "නැවතුම් කණු 4ක්", "එක් නැවතුම් කණුවක්", "එල්ලේ ක්‍රීඩාවේ 1, 2, 3 වන නැවතුම් පසුකර නැවත ප්‍රධාන ලකුණු පුවරුව (නිවස) වෙත පැමිණිය යුතුය."),
        q("එල්ලේ ක්‍රීඩාවේ පහර දෙන්නා විසින් ඉහළට ගසන ලද පන්දුවක් බිම පතිත වීමට පෙර රැකගැනීමෙන් සිදුවන දැවී යාම කුමක්ද?", "උඩපන්දුවක් රැකීමෙන් දැවී යාම (Catch out)", "දමා ගැසීමෙන් දැවී යාම", "ඉර කැපීමෙන් දැවී යාම", "කාලය ඉක්මවීමෙන් දැවී යාම", "පහර දුන් පන්දුව බිම නොවැටී රැකගත් විට පහර දුන් ක්‍රීඩකයා දැවී යයි."),
        q("එල්ලේ ක්‍රීඩාවේ ධාවකයා එක් නැවතුමක සිට ඊළඟ නැවතුමට දුවන අතරතුර පන්දුවෙන් ශරීරයේ දමා ගැසීමෙන් සිදුකරන දැවී යාම කුමක්ද?", "දමා ගැසීමෙන් දැවී යාම (Tag out / Throw out)", "උඩපන්දුවෙන් දැවී යාම", "අතින් ඇල්ලීමෙන් දැවී යාම", "කඩුල්ල බිඳීමෙන් දැවී යාම", "නැවතුම් කණුවක ස්පර්ශ නොවී දුවන අවස්ථාවේ පන්දුවෙන් ශරීරයේ පහර දීමෙන් ක්‍රීඩකයා දැවී යයි."),
        q("එල්ලේ ක්‍රීඩාවේ කණ්ඩායමකට එක් ඉනිමකදී හිමිවන උපරිම ක්‍රීඩක දැවී යාම් සංඛ්‍යාව කීයද?", "ක්‍රීඩකයන් 16 දෙනෙකු දැවී යාම", "ක්‍රීඩකයන් 11 දෙනෙකු", "ක්‍රීඩකයන් 10 දෙනෙකු", "ක්‍රීඩකයන් 15 දෙනෙකු", "එල්ලේ පිලක ලියාපදිංචි ක්‍රීඩකයන් අතරින් 16 දෙනෙකු දැවී ගිය පසු ඉනිම අවසන් වේ."),
        q("එල්ලේ ක්‍රීඩාවේ පන්දුවට පහර දෙන ක්‍රීඩකයාට පන්දුව නිවැරදිව ඔසවා දෙන ක්‍රීඩකයා හඳුන්වන්නේ කෙසේද?", "පන්දු ඔසවන්නා", "පන්දු යවන්නා", "කඩුලු රකින්නා", "නායකයා", "පහර දෙන්නා ඉල්ලන උසට හා ස්ථානයට පන්දුව නිවැරදිව උඩට දමන තැනැත්තා පන්දු ඔසවන්නා වේ."),
        q("පිහිනුම් ක්‍රීඩාවේ පිහිනුම් තටාකයේ එක් මංතීරුවක (Lane) සම්මත පළල මීටර් කීයද?", "මීටර් 2.5කි", "මීටර් 1.5කි", "මීටර් 3.0කි", "මීටර් 2.0කි", "ජාත්‍යන්තර සම්මත පිහිනුම් තටාකයක එක් මංතීරුවක පළල මීටර් 2.5ක් වේ."),
        q("පිහිනුම් ක්‍රීඩාවේ නිදහස් ආර (Freestyle) ඉසව්වකදී පිහිනුම් තටාක කෙළවරට ළඟා වූ පසු ආපසු හැරීම සඳහා බහුලව භාවිත කරන වේගවත් ක්‍රමය කුමක්ද?", "පෙරළි හැරවුම හෙවත් ෆ්ලිප් හැරවුම (Flip turn / Tumble turn)", "අතින් අල්ලා හැරීම", "ජලයෙන් ගොඩට පැන හැරීම", "නැවතී හැරීම", "ජලය යටින් ඉදිරියට කරණමක් ගසා දෙපාවලින් බිත්තියට තල්ලු වී හැරීම ෆ්ලිප් හැරවුමයි."),
        q("පසුපස ආර (Backstroke) පිහිනීමේදී ආරම්භය ලබාගන්නේ කෙසේද?", "ජලය තුළ සිට ආරම්භක ග්‍රහණය අල්ලාගෙන (In-water start)", "ආරම්භක පීඨිකාව මත සිට පැනීමෙන්", "තටාකය අයිනේ වාඩි වී", "ජලය තුළ සිට ඇවිදීමෙන්", "පසුපස ආර පිහිනුම්කරුවන් පමණක් ජලය තුළ බැස ආරම්භක හැඬලය අල්ලාගෙන තරගය අරඹයි."),
        q("ළය ආර (Breaststroke) සහ සමනල ආර (Butterfly) ඉසව්වලදී හැරවුමේදී හා තරගය අවසන් කිරීමේදී පිළිපැදිය යුතු අනිවාර්ය නීතිය කුමක්ද?", "දෑත් දෙකම එකවර සමගාමීව බිත්තියේ ස්පර්ශ කළ යුතුය (Two-hand touch)", "එක් අතකින් පමණක් ස්පර්ශ කිරීම", "හිසෙන් ස්පර්ශ කිරීම", "පාදයෙන් පමණක් ස්පර්ශ කිරීම", "මෙම ඉසව් දෙකේදීම හැරවුම් බිත්තියේ දෑත් දෙකම එකම මට්ටමක තබා එකවර ස්පර්ශ කිරීම අනිවාර්ය වේ."),
        q("පිහිනුම් තරගයක ආරම්භක සංඥාවට පෙර පිහිනුම් තටාකයට පැනීම හඳුන්වන්නේ කෙසේද?", "අසත්‍ය ආරම්භයක් (False start) ලෙස සලකා නුසුදුස්සකු කිරීම", "දඬුවම් තත්පර 5ක් එකතු කිරීම", "නැවත අවස්ථාවක් ලබාදීම", "ලකුණු අඩු කිරීම", "නූතන නීති අනුව පළමු අසත්‍ය ආරම්භයේදීම අදාළ පිහිනුම්කරු තරගයෙන් නුසුදුස්සකු (Disqualified) කෙරේ."),
        q("පිහිනුම් ක්‍රීඩකයා ජයග්‍රහණය තහවුරු කිරීම සඳහා නිමේෂ බිත්තියේ ස්පර්ශ කළ යුතු ස්වයංක්‍රීය ඉලෙක්ට්‍රොනික පුවරුව කුමක්ද?", "ස්පර්ශක පුවරුව (Electronic Touch Pad)", "කාල ඝණක ඔරලෝසුව", "ආරම්භක පුවරුව", "මිනුම් පටිය", "ක්‍රීඩකයාගේ අත ස්පර්ශ වන සැනින් කාලය සටහන් වන විද්‍යුත් ස්පර්ශක පුවරු තටාක කෙළවර සවිකර ඇත."),
        q("කණ්ඩායම් 12ක් සහභාගී වන තනි ලීග් (Single League) පාපන්දු තරගාවලියක මුළු තරග සංඛ්‍යාව ගණනය කරන සූත්‍රය සහ පිළිතුර කුමක්ද?", "N(N - 1) / 2 අනුව තරග 66කි", "තරග 12කි", "තරග 24කි", "තරග 132කි", "සූත්‍රය N(N - 1) / 2 = 12 × 11 / 2 = 66කි."),
        q("කණ්ඩායම් 8ක් සහභාගී වන ද්විත්ව ලීග් (Double League) වොලිබෝල් තරගාවලියක මුළු තරග සංඛ්‍යාව ගණනය කරන සූත්‍රය සහ පිළිතුර කුමක්ද?", "N(N - 1) අනුව තරග 56කි", "තරග 28කි", "තරග 16කි", "තරග 64කි", "ද්විත්ව ලීග් ක්‍රමයේදී සූත්‍රය N(N - 1) = 8 × 7 = 56කි."),
        q("බාස්කට්බෝල් (පැසිපන්දු) ක්‍රීඩා පිටියේ වළල්ලේ (Basket rim) සම්මත උස පොළොවේ සිට අඩි හෝ මීටර් කීයක්ද?", "අඩි 10ක් (මීටර් 3.05ක්)", "අඩි 8ක්", "අඩි 12ක්", "අඩි 9ක්", "පැසිපන්දු වළල්ල පොළොවේ සිට හරියටම අඩි 10ක් හෙවත් මීටර් 3.05ක් උසින් සවිකර ඇත."),
        q("පැසිපන්දු ක්‍රීඩාවේ එක් පිලකට ප්‍රතිවාදී වළල්ල වෙත පන්දුව විසි කර ප්‍රහාරයක් එල්ල කිරීම සඳහා ලබාදෙන උපරිම කාලය තත්පර කීයද?", "තත්පර 24ක ප්‍රහාරක කාලය (24-second shot clock)", "තත්පර 30ක්", "තත්පර 15ක්", "තත්පර 40ක්", "පන්දුව හිමි කරගත් මොහොතේ සිට තත්පර 24ක් ඇතුළත වළල්ල ඉලක්ක කර විදීමක් සම්පූර්ණ කළ යුතුය."),
        q("පැසිපන්දු ක්‍රීඩාවේ තම පසුපස අර්ධයේ සිට ඉදිරි අර්ධය වෙත පන්දුව ගෙන යාමට ලබාදෙන උපරිම කාලය තත්පර කීයද?", "තත්පර 8ක් (8-second rule)", "තත්පර 10ක්", "තත්පර 5ක්", "තත්පර 12ක්", "පසුපස අර්ධයෙන් පන්දුව ඉදිරියට ගෙන යාම සඳහා තත්පර 8ක උපරිම කාලයක් ලබාදේ."),
        q("පැසිපන්දු ක්‍රීඩාවේ දැඩි රැකවරණයක් යටතේ සිටින ක්‍රීඩකයෙකු පන්දුව අතැතිව පාස් කිරීමක් හෝ විදීමක් නොකර රැඳී සිටිය හැකි උපරිම කාලය තත්පර කීයද?", "තත්පර 5ක් (5-second closely guarded rule)", "තත්පර 3ක්", "තත්පර 8ක්", "තත්පර 10ක්", "ප්‍රතිවාදී ආරක්ෂකයෙකු මීටර් 1ක් ඇතුළත සිටින විට තත්පර 5කට වඩා පන්දුව තබාගත නොහැක."),
        q("පැසිපන්දු ක්‍රීඩාවේ ප්‍රහාරක පිලේ ක්‍රීඩකයෙකුට ප්‍රතිවාදී සීමාසහිත පෙදෙස (Key area / Restricted area) තුළ අඛණ්ඩව රැඳී සිටිය හැකි උපරිම කාලය කොපමණද?", "තත්පර 3ක් (3-second rule)", "තත්පර 5ක්", "තත්පර 8ක්", "තත්පර 10ක්", "ප්‍රහාරක කලාපයේ කී පෙදෙස තුළ තත්පර 3කට වඩා රැඳී සිටීම නීති විරෝධී වේ."),
        q("පැසිපන්දු ක්‍රීඩාවේදී දඬුවම් නිදහස් විදීමකින් (Free Throw) සාර්ථකව ලබාගන්නා එක් කූඩයකට හිමිවන ලකුණු සංඛ්‍යාව කීයද?", "ලකුණු 1කි", "ලකුණු 2කි", "ලකුණු 3කි", "ලකුණු 4කි", "දඬුවම් රේඛාවේ සිට කරන සාර්ථක නිදහස් විදීමකට ලකුණු 1ක් හිමිවේ."),
        q("පැසිපන්දු ක්‍රීඩාවේ මීටර් 6.75 ආරුක්කු රේඛාවෙන් (Three-point arc) පිටත සිට සාර්ථකව විදින ලද කූඩයකට හිමිවන ලකුණු සංඛ්‍යාව කීයද?", "ලකුණු 3කි", "ලකුණු 2කි", "ලකුණු 1කි", "ලකුණු 4කි", "මීටර් 6.75 සීමාවෙන් පිටත සිට වළල්ලට දමන ඕනෑම සාර්ථක කූඩයකට ලකුණු 3ක් හිමිවේ."),
        q("පැසිපන්දු ක්‍රීඩාවේ සාමාන්‍ය ක්‍රීඩා පිටිය තුළ ආරුක්කු රේඛාවෙන් ඇතුළත සිට සාර්ථකව දමන සාමාන්‍ය කූඩයකට (Field Goal) හිමිවන ලකුණු සංඛ්‍යාව කීයද?", "ලකුණු 2කි", "ලකුණු 1කි", "ලකුණු 3කි", "ලකුණු 4කි", "ආරුක්කු රේඛාව ඇතුළත සිට විදින සෑම සාර්ථක කූඩයකටම ලකුණු 2ක් බැගින් ලැබේ."),
        q("පැසිපන්දු ක්‍රීඩකයෙකු පන්දුව බිම නොගසා (Dribble නොකර) පියවර දෙකකට වඩා ගමන් කිරීම හඳුන්වන නීති විරෝධී වරද කුමක්ද?", "පියවර වරද හෙවත් ට්‍රැවලිං (Travelling violation)", "ඩබල් ඩ්‍රිබ්ල්", "පෞද්ගලික වරද", "බාධා කිරීම", "පන්දුව අතැතිව බිම නොගසා පියවර දෙකකට වඩා තැබීම ට්‍රැවලිං වරදකි."),
        q("පැසිපන්දු ක්‍රීඩකයෙකු පන්දුව බිම ගසා (Dribble කර) අත් දෙකෙන්ම අල්ලා නැවත බිම ගසමින් ගමන් කිරීම හඳුන්වන්නේ කෙසේද?", "ද්විත්ව බිම ගැසීමේ වරද හෙවත් ඩබල් ඩ්‍රිබ්ල් (Double dribble)", "ට්‍රැවලිං", "පාද වරද", "ප්‍රහාරක වරද", "වරක් ඩ්‍රිබ්ල් කර නැවැත්වූ පසු නැවත ඩ්‍රිබ්ල් කිරීම හෝ අත් දෙකෙන්ම එකවර ඩ්‍රිබ්ල් කිරීම ද්විත්ව ඩ්‍රිබ්ල් වරදකි."),
        q("පැසිපන්දු ක්‍රීඩකයෙකුට එක් තරගයක් තුළ සිදුකළ හැකි උපරිම පෞද්ගලික වැරදි (Personal fouls) ගණන කීයද?", "වැරදි 5කි (5 වන වරදින් පසු තරගයෙන් ඉවත් කෙරේ)", "වැරදි 3කි", "වැරදි 6කි", "වැරදි 4කි", "ජාත්‍යන්තර FIBA නීති අනුව පෞද්ගලික වැරදි 5ක් කළ ක්‍රීඩකයා තරගයෙන් ඉවත් විය යුතුය."),
        q("පැසිපන්දු කණ්ඩායමකට එක් කාර්තුවකදී දඬුවම් නිදහස් විසි කිරීම් නොලබා සිදුකළ හැකි උපරිම කණ්ඩායම් වැරදි සංඛ්‍යාව කීයද?", "වැරදි 4කි (5 වන වරදේ සිට දඬුවම් විසි කිරීම් හිමිවේ)", "වැරදි 2ක්", "වැරදි 6ක්", "වැරදි 3ක්", "එක් කාර්තුවකදී පිලක 5 වන කණ්ඩායම් වරදේ සිට ප්‍රතිවාදීන්ට නිදහස් විදීම් 2ක් හිමිවේ."),
        q("පිහිනුම් ක්‍රීඩාවේ මිශ්‍ර ආර සහය (Medley Relay) ඉසව්වේදී පිහිනුම් ආරවල් හතර ක්‍රියාත්මක වන නිවැරදි අනුපිළිවෙළ කුමක්ද?", "පසුපස ආර, ළය ආර, සමනල ආර, නිදහස් ආර", "නිදහස් ආර, පසුපස ආර, ළය ආර, සමනල ආර", "ළය ආර, සමනල ආර, පසුපස ආර, නිදහස් ආර", "සමනල ආර, පසුපස ආර, ළය ආර, නිදහස් ආර", "මිශ්‍ර සහය ඉසව්ව Backstroke වලින් ආරම්භ වී Breaststroke, Butterfly සහ Freestyle ලෙස අවසන් වේ."),
        q("පිහිනුම් ක්‍රීඩාවේ තනි පුද්ගල මිශ්‍ර ආර (Individual Medley — IM) ඉසව්වේදී ක්‍රීඩකයා පිහිනිය යුතු නිවැරදි ආර අනුපිළිවෙළ කුමක්ද?", "සමනල ආර, පසුපස ආර, ළය ආර, නිදහස් ආර", "පසුපස ආර, ළය ආර, සමනල ආර, නිදහස් ආර", "නිදහස් ආර, සමනල ආර, පසුපස ආර, ළය ආර", "ළය ආර, සමනල ආර, නිදහස් ආර, පසුපස ආර", "තනි පුද්ගල මිශ්‍ර ආර ඉසව්ව ආරම්භ වන්නේ Butterfly වලිනි. ඉන්පසු Backstroke, Breaststroke සහ Freestyle වේ."),
        q("සමනල ආර පිහිනීමේදී හා ආරම්භයේදී ජලය යටින් පාද දෙකම එකට තබා සිදුකරන තරංගාකාර පා පහර හඳුන්වන්නේ කෙසේද?", "ඩොල්ෆින් පා පහර (Dolphin kick)", "මැඩි පා පහර", "කතුරු පා පහර", "පාවෙන පා පහර", "සමනල ආරේදී දෑත් මෙන්ම දෙපාද එකවර තරංගාකාරව ගැසීම ඩොල්ෆින් කික් නම් වේ."),
        q("පිහිනුම් ක්‍රීඩාවේ ජල ප්‍රතිරෝධය අවම කරමින් උපරිම ඉදිරි ගම්‍යතාවක් ලබාගැනීමට ගන්නා ශරීර ඉරියව්ව කුමක්ද?", "ධාරාරේඛී ඉරියව්ව (Streamline position)", "සිරස් ඉරියව්ව", "වක්‍ර ඉරියව්ව", "ලිහිල් ඉරියව්ව", "දෑත් හිසට ඉහළින් තද කර ශරීරය ඊතලයක් සේ තබා ගැනීම ධාරාරේඛී පිහිටුමයි."),
        q("ජල පෝලෝ (Water Polo) කණ්ඩායමක එකවර ජලය තුළ ක්‍රීඩා කරන නිල ක්‍රීඩකයන් සංඛ්‍යාව කීයද?", "ගෝල රකින්නා ඇතුළුව ක්‍රීඩකයන් 7කි", "ක්‍රීඩකයන් 6කි", "ක්‍රීඩකයන් 5කි", "ක්‍රීඩකයන් 11කි", "ජල පෝලෝ ක්‍රීඩාවේදී එක් කණ්ඩායමකින් ක්‍රීඩකයන් 7 දෙනෙකු ජලයේ ක්‍රීඩා කරයි."),
        q("ජලයේ ගිලෙන පුද්ගලයෙකු බේරාගැනීමේදී (Life saving) ජීවිතාරක්ෂකයා විසින් අනුගමනය කළ යුතු ආරක්ෂිතම පියවර අනුපිළිවෙළ කුමක්ද?", "ළඟා වීම, විසිකිරීම, ඔරුවකින් යාම, පිහිනා යාම (Reach, Throw, Row, Go)", "පිහිනා යාම, විසිකිරීම, ළඟා වීම", "ඔරුවෙන් යාම, පැනීම, විසිකිරීම", "කෙළින්ම ජලයට පැන අල්ලා ගැනීම", "ජීවිතාරක්ෂකයා මුලින්ම ගොඩබිම සිට ලීයක් හෝ කඹයක් දිගු කිරීම, පාවෙන යමක් විසිකිරීම ආදිය කළ යුතු අතර ජලයට බැසීම අවසන් පියවරයි."),
        q("පිළිමළුන් පිටුදැකීමේ (Knockout) තරගාවලියක පළමු වටයෙන් පරාජය වන කණ්ඩායම්වලට තවදුරටත් ක්‍රීඩා කිරීමට අවස්ථාව සලසන තරගාවලි ක්‍රමය කුමක්ද?", "අස්වැසිලි තරගාවලි (Consolation Tournaments)", "ද්විත්ව ලීග් ක්‍රමය", "සුපිරි ලීග් ක්‍රමය", "තනි තරග ක්‍රමය", "පළමු වටයේ පරාජිතයන් අතර වෙනම ශූරතාවක් සඳහා පවත්වන තරගාවලි අස්වැසිලි තරගාවලි වේ."),
        q("පිළිමළුන් පිටුදැකීමේ තරගාවලියක කණ්ඩායම් සංඛ්‍යාව 2හි බලයක් (Power of 2) නොවන විට පළමු වටයේ තරග නොකර දෙවන වටයට සුදුසුකම් ලැබීම හඳුන්වන්නේ කෙසේද?", "බායි අවස්ථාවක් (Bye) ලබාදීම", "ශ්‍රේණිගත කිරීම", "ලීග් අවස්ථාව", "දඬුවම් වටය", "කණ්ඩායම් ගණන 2හි බලයක් නොවන විට ඉදිරි වටය සමබර කිරීම සඳහා බායි ලබාදේ."),
        q("කණ්ඩායම් 11ක් සහභාගී වන පිළිමළුන් පිටුදැකීමේ තරගාවලියක පළමු වටයේදී ලබාදිය යුතු සම්පූර්ණ බායි (Byes) සංඛ්‍යාව කොපමණද?", "බායි 5කි (16 - 11 = 5)", "බායි 3කි", "බායි 4කි", "බායි 6කි", "ඊළඟ ඉහළම 2හි බලය 16 වන බැවින් 16 - 11 = බායි 5ක් හිමිවේ."),
        q("කණ්ඩායම් 20ක් සහභාගී වන පිළිමළුන් පිටුදැකීමේ තරගාවලියක ලබාදිය යුතු සම්පූර්ණ බායි (Byes) සංඛ්‍යාව කොපමණද?", "බායි 12කි (32 - 20 = 12)", "බායි 8කි", "බායි 10කි", "බායි 4කි", "ඊළඟ ඉහළම 2හි බලය 32 වන බැවින් 32 - 20 = බායි 12ක් හිමිවේ."),
        q("කණ්ඩායම් 16ක් සහභාගී වන සාමාන්‍ය පිළිමළුන් පිටුදැකීමේ තරගාවලියක සමස්ත තරගාවලිය නිමවීමට පැවැත්විය යුතු වට සංඛ්‍යාව කීයද?", "වට 4කි (Rounds 4)", "වට 3කි", "වට 5කි", "වට 8කි", "16 = 2^4 වන බැවින් තරග වට 4ක් (පළමු වටය, අර්ධ අවසන්, අවසන් පූර්ව, අවසන්) පැවැත්වේ."),
        q("තරගාවලියක දක්ෂතම කණ්ඩායම් පළමු වටවලදීම එකිනෙකා හමුවී ඉවත් වීම වැළැක්වීම සඳහා භාවිත කරන ක්‍රමය කුමක්ද?", "ශ්‍රේණිගත කිරීම හෙවත් සීඩිං කිරීම (Seeding)", "බායි ලබාදීම", "කාසියේ වාසිය බැලීම", "ලීග් ක්‍රමය", "දක්ෂතම පිල් දෙක තරග සටහනේ උඩම සහ යටම කෙළවරවල තැබීම සීඩිං කිරීමයි."),
        q("දෙවරක් පරාජය වන තෙක් කිසිදු කණ්ඩායමක් තරගාවලියෙන් ඉවත් නොවන තරග ක්‍රමය කුමක්ද?", "ද්විත්ව පිළිමළුන් පිටුදැකීමේ ක්‍රමය (Double Elimination Tournament)", "තනි පිළිමළුන් පිටුදැකීමේ ක්‍රමය", "තනි ලීග් ක්‍රමය", "ස්විස් ක්‍රමය", "ද්විත්ව පිළිමළුන් ක්‍රමයේදී ජයග්‍රාහකයන්ගේ සහ පරාජිතයන්ගේ ලෙස වරහන් දෙකක් පවත්වාගෙන යයි."),
        q("ලීග් තරගාවලියක කණ්ඩායම් දෙකක් සමාන ප්‍රසාද ලකුණු ලබාගත් විට ශ්‍රේණිගත කිරීම සඳහා මුලින්ම සලකා බලන මිනුම කුමක්ද?", "ගෝල හෝ ලකුණු වෙනස (Goal Difference / Run Rate)", "කාසියේ වාසිය", "වයස", "කණ්ඩායමේ නමේ අකුරු", "ලකුණු සමාන වූ විට ලබාගත් ගෝල සහ ලබාදුන් ගෝල අතර ශුද්ධ වෙනස සලකා බලයි."),
        q("ක්‍රීඩාවේදී නීති රීතිවලට ගරු කරමින් විනිසුරු තීරණ පිළිගනිමින් ප්‍රතිවාදියාට ගෞරව කිරීම හඳුන්වන පොදු සංකල්පය කුමක්ද?", "ක්‍රීඩාශීලීත්වය හෙවත් සාධාරණ ක්‍රීඩාව (Fair Play / Sportsmanship)", "ක්‍රීඩා ආක්‍රමණශීලීත්වය", "තරගකාරීත්වය", "ජයග්‍රහණ පිපාසය", "ජය පරාජය උපේක්ෂාවෙන් විඳදරා ගනිමින් විනයගරුකව ක්‍රීඩා කිරීම ක්‍රීඩාශීලීත්වයයි."),
        q("තරගයකදී හෝ පුහුණුවකදී තහනම් උත්තේජක භාවිතය වැළැක්වීම සඳහා ජාත්‍යන්තරව ක්‍රියාත්මක වන ප්‍රධාන ආයතනය කුමක්ද?", "ලෝක තහනම් උත්තේජක මර්දන නියෝජිතායතනය (WADA)", "FIFA ආයතනය", "IOC ආයතනය", "WHO ආයතනය", "WADA (World Anti-Doping Agency) ක්‍රීඩාවේ පාරිශුද්ධත්වය රැකීමට තහනම් උත්තේජක පරීක්ෂණ පවත්වයි."),
        q("පාපන්දු ක්‍රීඩාවේ පන්දුව පාලනය කරමින් වේගයෙන් ඉදිරියට ගෙන යාමේ මූලික කුසලතාව කුමක්ද?", "පන්දු ධාවනය හෙවත් ඩ්‍රිබ්ලිං කිරීම (Dribbling)", "පන්දු පිරිනැමීම", "හිසෙන් පහර දීම", "ගෝල් කික් ගැසීම", "පාදයේ ඇතුළත හෝ පිටත යොදාගෙන පන්දුව පාලනයෙන් යුතුව රැගෙන යාම ඩ්‍රිබ්ලිං කිරීමයි."),
        q("පාපන්දු ක්‍රීඩාවේ පන්දුව හිසෙන් පහර දී ඉලක්කය වෙත හෝ සගයෙකු වෙත යොමු කිරීම හඳුන්වන්නේ කෙසේද?", "හිසෙන් පහර දීම (Heading)", "පන්දු රැකීම", "ටැකල් කිරීම", "බ්ලොක් කිරීම", "හිසේ නළල් ප්‍රදේශය භාවිත කරමින් වාතයේ එන පන්දුවකට පහර දීම Heading වේ."),
        q("දැල්පන්දු ක්‍රීඩාවේ ක්‍රීඩිකාවන් 7 දෙනා අතරින් ප්‍රතිවාදී ගෝල කවය තුළට ඇතුළු වී ලකුණු ලබාගත හැකි ක්‍රීඩිකාවන් දෙදෙනා කවුරුන්ද?", "ගෝල විදින්නී (GS) සහ ගෝල ප්‍රහාරිකාව (GA)", "මධ්‍ය ක්‍රීඩිකාව සහ පියාපත් ප්‍රහාරිකාව", "ගෝල රකින්නී සහ ගෝල ආරක්ෂිකාව", "පියාපත් ආරක්ෂිකාව සහ මධ්‍ය ක්‍රීඩිකාව", "දැල්පන්දු පිටියේ ගෝල ලබාගැනීමේ හැකියාව ඇත්තේ GS සහ GA යන ක්‍රීඩිකාවන් දෙදෙනාට පමණි."),
        q("දැල්පන්දු ක්‍රීඩාවේ මුළු පිටිය පුරාම (ගෝල කව දෙක හැර) නිදහසේ ක්‍රීඩා කළ හැකි එකම ක්‍රීඩිකාව කවුරුන්ද?", "මධ්‍ය ක්‍රීඩිකාව (Center — C)", "ගෝල විදින්නී", "ගෝල රකින්නී", "පියාපත් ආරක්ෂිකාව", "මධ්‍ය ක්‍රීඩිකාවට ගෝල කව දෙක හැර අනෙක් මුළු පිටියේම (Thirds තුනෙහිම) ක්‍රීඩා කළ හැක."),
        q("දැල්පන්දු ක්‍රීඩාවේ ගෝල ආරක්ෂක කවය තුළ සිටිමින් ප්‍රතිවාදී GS ට ගෝල විදීමට බාධා කරන ප්‍රධාන ක්‍රීඩිකාව කවුරුන්ද?", "ගෝල රකින්නී (Goal Keeper — GK)", "පියාපත් ආරක්ෂිකාව", "මධ්‍ය ක්‍රීඩිකාව", "ගෝල ප්‍රහාරිකාව", "තම පිලේ ගෝල කවය තුළ සිටිමින් ප්‍රතිවාදී ගෝල විදින්නිය වළක්වන්නේ ගෝල රකින්නියයි."),
        q("ක්‍රිකට් ක්‍රීඩාවේ පන්දු යවන්නා තම අත මුදාහරින මොහොතේ පිතිකරු අන්තයේ ක්‍රීඩකයා ක්‍රීස් ඉරෙන් ඉදිරියට ගියහොත් පන්දු යවන්නා කඩුල්ල බිඳ දැමීම හඳුන්වන්නේ කෙසේද?", "මන්කාඩ් දැවී යාම (Run out at non-striker's end)", "හිට් විකට් දැවී යාම", "ස්ටම්ප් කිරීමෙන් දැවී යාම", "කාලය ඉක්මවීමෙන් දැවී යාම", "පන්දු යැවීමට පෙර ක්‍රීස් ඉරෙන් පිටතට යන පිතිකරුවා දුවද්දී දැවී යාමකට ලක් කිරීම මන්කාඩ් ක්‍රමයයි."),
        q("ක්‍රිකට් ක්‍රීඩාවේ පන්දුව පිත්තේ වැදී පිටුපසින් කඩුලු රකින්නා අතට හෝ ස්ලිප් පන්දු රකින්නා වෙත යන විට ලබාගන්නා උඩපන්දුව කුමක්ද?", "දාරයේ වැදී දැවී යාම (Caught behind / Edge)", "කඩුල්ල මුවා කිරීම", "ස්ටම්ප් කිරීම", "හිට් විකට්", "පිත්තේ දාරයේ වැදී පිටුපසට යන පන්දුව රැකගැනීමෙන් පිතිකරු දැවී යයි."),
        q("වොලිබෝල් ක්‍රීඩාවේ ප්‍රතිවාදී ප්‍රහාරයක් සාර්ථකව පාලනය කර ගනිමින් බිම පතිත වීමට නොදී උඩට එසවීම හඳුන්වන්නේ කෙසේද?", "ඩිග් කිරීම හෙවත් පන්දු ගොඩගැනීම (Dig pass)", "ස්පයික් කිරීම", "බ්ලොක් කිරීම", "සර්ව් කිරීම", "පහතින් එන වේගවත් ප්‍රහාරක පන්දු යටි අත් පහරින් ඉහළට ගොඩගැනීම ඩිග් කිරීමයි."),
        q("වොලිබෝල් ක්‍රීඩාවේ දැල අසල සිට පනින ප්‍රහාරකයා පහළට වැටෙන පරිදි වේගයෙන් එල්ල කරන පහර කුමක්ද?", "ප්‍රහාරක පහර හෙවත් ස්පයික් පහර (Spike / Smash)", "ඩිග් පහර", "සකසන පහර", "රැකීමේ පහර", "දැලට ඉහළින් පන්දුවට අත්ලෙන් පහර දී ප්‍රතිවාදී පිටියේ බිම පතිත කරවීම ස්පයික් පහරයි."),
        q("වොලිබෝල් ක්‍රීඩාවේ පිලක් එක් වටයකදී ලබාගත හැකි උපරිම ක්‍රීඩක ආදේශන (Substitutions) සංඛ්‍යාව කීයද?", "ආදේශන 6ක්", "ආදේශන 3ක්", "ආදේශන 12ක්", "අසීමිත ආදේශන", "එක් වටයකදී කණ්ඩායමකට කළ හැකි උපරිම නිල ක්‍රීඩක ආදේශන සංඛ්‍යාව 6කි."),
        q("වොලිබෝල් තරගයකදී කණ්ඩායමකට එක් වටයක් තුළ ලබාගත හැකි උපරිම කාල විරාම (Time-outs) සංඛ්‍යාව කීයද?", "තත්පර 30 බැගින් වූ කාල විරාම 2ක්", "විනාඩිය බැගින් වූ කාල විරාම 3ක්", "එක් කාල විරාමයක් පමණි", "කාල විරාම 4ක්", "එක් වටයකදී කණ්ඩායමකට ඉල්ලා සිටිය හැක්කේ තත්පර 30 බැගින් වූ කාල විරාම 2ක් පමණි."),
        q("පාපන්දු ක්‍රීඩා තරගයක සාමාන්‍ය තරග කාලය අතිරේක කාලයකින් තොරව විනාඩි කීයක්ද?", "විනාඩි 45 බැගින් වූ අඩ 2ක් (මුළු විනාඩි 90ක්)", "විනාඩි 30 බැගින් අඩ 2ක්", "විනාඩි 40 බැගින් අඩ 2ක්", "විනාඩි 60ක්", "සම්මත පාපන්දු තරගයක් මිනිත්තු 45ක අර්ධ දෙකකින් සමන්විත වන අතර මුළු කාලය විනාඩි 90කි."),
        q("පාපන්දු ක්‍රීඩාවේ තරගය සම තත්ත්වයෙන් නිම වූ විට ජයග්‍රාහකයා තේරීමට ලබාදෙන අතිරේක කාලය (Extra Time) කොපමණද?", "විනාඩි 15 බැගින් වූ අඩ 2ක් (මුළු විනාඩි 30ක්)", "විනාඩි 10 බැගින් අඩ 2ක්", "විනාඩි 20ක එක් අඩක්", "විනාඩි 5 බැගින් අඩ 2ක්", "අවසන් තරගවලදී සම ලකුණු බිඳීමට මිනිත්තු 15 බැගින් වූ අර්ධ දෙකක් (මිනිත්තු 30ක්) ලබාදේ."),
        q("පාපන්දු ක්‍රීඩාවේ අතිරේක කාලයෙන් පසුවත් ජයග්‍රාහකයෙකු නොසිටි විට ක්‍රියාත්මක කරන ක්‍රමය කුමක්ද?", "දඬුවම් පහර 5 බැගින් එල්ල කිරීම (Penalty Shootout)", "කාසියේ වාසිය බැලීම", "තරගය අත්හැර දැමීම", "කෝනර් කික් ගණන බැලීම", "අතිරේක කාලයෙන් පසු දෙපිලටම දඬුවම් පහර 5 බැගින් ලබාදී ජයග්‍රාහකයා තීරණය කරයි."),
        q("පිහිනුම් ක්‍රීඩාවේ පිරිමි මීටර් 4 × 100 නිදහස් ආර සහය ඉසව්වකදී පිහිනිය යුතු මුළු දුර කොපමණද?", "මීටර් 400කි (එක් අයෙකුට මීටර් 100 බැගින්)", "මීටර් 200කි", "මීටර් 800කි", "මීටර් 100කි", "කණ්ඩායමේ ක්‍රීඩකයන් 4 දෙනා පිළිවෙළින් මීටර් 100 බැගින් මුළු මීටර් 400ක් පිහිනයි."),
        q("ක්‍රීඩා තරගාවලියක් සංවිධානය කිරීමේදී තරග සැලැස්ම (Fixture) කලින් සකස් කර කණ්ඩායම්වලට දැනුම් දීමේ ප්‍රධාන වාසිය කුමක්ද?", "තරගාවලිය විනිවිදභාවයෙන් හා විධිමත්ව නියමිත වේලාවට පැවැත්වීමට හැකිවීම", "ජයග්‍රාහකයා කලින්ම තීරණය වීම", "ක්‍රීඩා පිටියේ ඉඩ ඉතිරි වීම", "විනිසුරුවන්ගේ වැටුප් අඩු වීම", "පූර්ව සැලසුම් කළ තරග සටහනක් තිබීමෙන් කණ්ඩායම්වලට සූදානම් වීමට සහ විධිමත්ව තරග පැවැත්වීමට පහසු වේ.")
    )
}
